import"https://cdnjs.cloudflare.com/ajax/libs/flowbite/2.3.0/flowbite.min.js";import"./Footer.astro_astro_type_script_index_0_lang.B9DQwTob.js";document.addEventListener("DOMContentLoaded",function(){const o=document.querySelectorAll("#bookTabs button"),d=document.querySelectorAll("#bookTabsContent > div");o.forEach(t=>{t.addEventListener("click",()=>{o.forEach(e=>e.classList.remove("active","text-blvd-white","bg-blvd-green")),t.classList.add("active","text-blvd-white","bg-blvd-green"),d.forEach(e=>e.classList.add("hidden")),document.querySelector(t.dataset.tabsTarget).classList.remove("hidden")})})});
